WITH enriched AS (SELECT *, SUM(amount) OVER (PARTITION BY method ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS amount_sum_7d, COUNT(amount) OVER (PARTITION BY YEAR(paid_at), method ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS amount_count_30d, LAG(amount, 1) OVER (PARTITION BY method ORDER BY amount, id) AS prev_amount, ROUND(amount / SUM(amount) OVER (PARTITION BY order_id), 4) AS amount_share FROM payments WHERE order_id IN (10, 24)) SELECT order_id, SUM(CASE WHEN method = 'paypal' THEN amount_sum_7d ELSE 0 END) AS paypal_amount_sum_7d, COUNT_IF(status = 'SUCCESS') AS success_events, SUM(CASE WHEN status = 'REFUNDED' THEN amount_count_30d ELSE 0 END) AS refunded_amount_count_30d, SUM(CASE WHEN method = 'card' THEN prev_amount ELSE 0 END) AS card_prev_amount FROM enriched GROUP BY order_id HAVING COUNT_IF(status = 'SUCCESS') > 1 ORDER BY order_id DESC NULLS LAST;
